        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextHelper.CreateSeededContext();
            _controller = new StudentsController(_context);

            // Set up TempData for controller
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(), 
                new Mock_ITempDataProvider());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        // Simple ITempDataProvider for tests
        private class Mock_ITempDataProvider : ITempDataProvider
        {
            private Dictionary<string, object?> _data = new();
            public IDictionary<string, object?> LoadTempData(HttpContext context) => _data;
            public void SaveTempData(HttpContext context, IDictionary<string, object?> values) => _data = new Dictionary<string, object?>(values!);
        }

        #region Index

        [Fact]
        public void Index_NoParameters_ReturnsViewWithStudents()
        {
            // Act
            var result = _controller.Index(null, null, null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.Equal(3, model.Count);
        }

        [Fact]
        public void Index_NameDescSort_ReturnsSortedByLastNameDescending()
        {
            // Act
            var result = _controller.Index("name_desc", null, null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.Equal("Anand", model[0].LastName);
        }

        [Fact]
        public void Index_DateSort_ReturnsSortedByDateAscending()
        {
            // Act
            var result = _controller.Index("Date", null, null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            // Alexander (2010) should come first
            Assert.Equal("Alexander", model[0].LastName);
        }

        [Fact]
        public void Index_DateDescSort_ReturnsSortedByDateDescending()
        {
            // Act
            var result = _controller.Index("date_desc", null, null, null) as ViewResult;

            // Assert
