using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestDbContextHelper.CreateSeededContext();
            _controller = new InstructorsController(_context);
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(),
                new Mock_ITempDataProvider());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private class Mock_ITempDataProvider : ITempDataProvider
        {
            private Dictionary<string, object?> _data = new();
            public IDictionary<string, object?> LoadTempData(HttpContext context) => _data;
            public void SaveTempData(HttpContext context, IDictionary<string, object?> values) => _data = new Dictionary<string, object?>(values!);
        }

        #region Index

        [Fact]
        public void Index_NoParameters_ReturnsViewWithInstructors()
        {
            // Arrange - Need to add CourseAssignments to avoid null reference
            foreach (var instructor in _context.Instructors)
            {
                if (instructor.CourseAssignments == null)
                    instructor.CourseAssignments = new List<CourseAssignment>();
            }
            _context.SaveChanges();

            // Act
            var result = _controller.Index(null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<ContosoUniversity.Models.SchoolViewModels.InstructorIndexData>(result.Model);
            Assert.NotNull(model.Instructors);
            Assert.Equal(2, model.Instructors.Count());
        }

        [Fact]
        public void Index_WithInstructorId_ReturnsCourses()
        {
            // Arrange
            var instructor = _context.Instructors.First();
            var course = _context.Courses.First();
            _context.CourseAssignments.Add(new CourseAssignment
            {
                InstructorID = instructor.ID,
                CourseID = course.CourseID
            });
            _context.SaveChanges();

