using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextHelper.CreateContext();
            _controller = new NotificationsController(_context);
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(),
                new Mock_ITempDataProvider());

            // Drain static queue
            var svc = new ContosoUniversity.Services.NotificationService();
            while (svc.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private class Mock_ITempDataProvider : ITempDataProvider
        {
            private Dictionary<string, object?> _data = new();
            public IDictionary<string, object?> LoadTempData(HttpContext context) => _data;
            public void SaveTempData(HttpContext context, IDictionary<string, object?> values) => _data = new Dictionary<string, object?>(values!);
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
        {
            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var jsonResult = result;
            Assert.NotNull(jsonResult.Value);
            // Check the anonymous type has success = true
            var value = jsonResult.Value;
            var successProp = value!.GetType().GetProperty("success");
            Assert.NotNull(successProp);
            Assert.True((bool)successProp.GetValue(value)!);
            var countProp = value.GetType().GetProperty("count");
            Assert.NotNull(countProp);
            Assert.Equal(0, (int)countProp.GetValue(value)!);
        }

        [Fact]
        public void GetNotifications_WithMessages_ReturnsNotifications()
        {
            // Arrange - send a notification via the service
            var svc = new ContosoUniversity.Services.NotificationService();
            svc.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var value = result.Value!;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(value)!);
            var countProp = value.GetType().GetProperty("count");
            Assert.Equal(1, (int)countProp!.GetValue(value)!);
        }

        [Fact]
        public void GetNotifications_LimitsTo10Messages()
        {
            // Arrange
            var svc = new ContosoUniversity.Services.NotificationService();
            for (int i = 0; i < 15; i++)
            {
                svc.SendNotification("Student", i.ToString(), $"Student {i}", EntityOperation.CREATE, "Admin");
            }

            // Act
            var result = _controller.GetNotifications();

            // Assert
            var value = result.Value!;
            var countProp = value.GetType().GetProperty("count");
            Assert.Equal(10, (int)countProp!.GetValue(value)!);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            // Act
            var result = _controller.MarkAsRead(1);

            // Assert
            Assert.NotNull(result);
            var value = result.Value!;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(value)!);
        }

        [Fact]
        public void Index_ReturnsView()
        {
            // Act
            var result = _controller.Index() as ViewResult;

            // Assert
            Assert.NotNull(result);
        }
    }
}

