namespace ContosoUniversity.Tests
{
    public class HomeControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly HomeController _controller;

        public HomeControllerTests()
        {
            _context = TestDbContextHelper.CreateSeededContext();
            _controller = new HomeController(_context);
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(),
                new Mock_ITempDataProvider());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private class Mock_ITempDataProvider : ITempDataProvider
        {
            private Dictionary<string, object?> _data = new();
            public IDictionary<string, object?> LoadTempData(HttpContext context) => _data;
            public void SaveTempData(HttpContext context, IDictionary<string, object?> values) => _data = new Dictionary<string, object?>(values!);
        }

        [Fact]
        public void Index_ReturnsView()
        {
            // Act
            var result = _controller.Index() as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        [Fact]
        public void About_ReturnsViewWithEnrollmentGroups()
        {
            // Act
            var result = _controller.About() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);
            Assert.NotEmpty(model);
        }

        [Fact]
        public void About_GroupsStudentsByEnrollmentDate()
        {
            // Act
            var result = _controller.About() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);

            // We have 3 students with different enrollment dates
            // Alexander: 2010-09-01, Alonso: 2012-09-01, Anand: 2013-09-01
            Assert.Equal(3, model.Count);

            // Each group has 1 student
            Assert.All(model, g => Assert.Equal(1, g.StudentCount));
        }

        [Fact]
        public void Contact_ReturnsViewWithMessage()
        {
            // Act
            var result = _controller.Contact() as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Your contact page.", _controller.ViewBag.Message);
        }

        [Fact]
        public void Error_ReturnsView()
        {
            // Act
            var result = _controller.Error() as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        [Fact]
        public void Unauthorized_ReturnsViewWithMessage()
        {
            // Act
            var result = _controller.Unauthorized() as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.Contains("permission", (string)_controller.ViewBag.Message);
        }
    }
}

