using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_EmptyDatabase_SeedsStudents()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(8, context.Students.Count());
            Assert.Contains(context.Students, s => s.LastName == "Alexander" && s.FirstMidName == "Carson");
            Assert.Contains(context.Students, s => s.LastName == "Alonso" && s.FirstMidName == "Meredith");
            Assert.Contains(context.Students, s => s.LastName == "Olivetto" && s.FirstMidName == "Nino");
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsInstructors()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(5, context.Instructors.Count());
            Assert.Contains(context.Instructors, i => i.LastName == "Abercrombie" && i.FirstMidName == "Kim");
            Assert.Contains(context.Instructors, i => i.LastName == "Zheng" && i.FirstMidName == "Roger");
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsDepartments()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(4, context.Departments.Count());
            Assert.Contains(context.Departments, d => d.Name == "English" && d.Budget == 350000);
            Assert.Contains(context.Departments, d => d.Name == "Mathematics" && d.Budget == 100000);
            Assert.Contains(context.Departments, d => d.Name == "Engineering" && d.Budget == 350000);
            Assert.Contains(context.Departments, d => d.Name == "Economics" && d.Budget == 100000);
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsCourses()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(7, context.Courses.Count());
            Assert.Contains(context.Courses, c => c.Title == "Chemistry" && c.Credits == 3);
            Assert.Contains(context.Courses, c => c.Title == "Calculus" && c.Credits == 4);
            Assert.Contains(context.Courses, c => c.Title == "Literature" && c.Credits == 4);
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsEnrollments()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(11, context.Enrollments.Count());
            Assert.Contains(context.Enrollments, e => e.Grade == Grade.A);
            Assert.Contains(context.Enrollments, e => e.Grade == Grade.B);
            Assert.Contains(context.Enrollments, e => e.Grade == Grade.C);
            Assert.Contains(context.Enrollments, e => e.Grade == null); // Anand's Chemistry enrollment
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsOfficeAssignments()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(3, context.OfficeAssignments.Count());
            Assert.Contains(context.OfficeAssignments, o => o.Location == "Smith 17");
            Assert.Contains(context.OfficeAssignments, o => o.Location == "Gowan 27");
            Assert.Contains(context.OfficeAssignments, o => o.Location == "Thompson 304");
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsCourseAssignments()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(8, context.CourseAssignments.Count());
        }

        [Fact]
        public void Initialize_AlreadySeeded_DoesNotDuplicate()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);
            var firstStudentCount = context.Students.Count();
