using ContosoUniversity.Models;
using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class ModelTests
    {
        #region Person / Student / Instructor

        [Fact]
        public void Person_FullName_ReturnsConcatenatedLastAndFirst()
        {
            // Arrange
            var student = new Student { LastName = "Smith", FirstMidName = "John" };

            // Act
            var fullName = student.FullName;

            // Assert
            Assert.Equal("Smith, John", fullName);
        }

        [Fact]
        public void Student_EnrollmentDate_DefaultsToMinValue()
        {
            // Arrange & Act
            var student = new Student();

            // Assert
            Assert.Equal(default(DateTime), student.EnrollmentDate);
        }

        [Fact]
        public void Student_Enrollments_CanBeInitialized()
        {
            // Arrange & Act
            var student = new Student
            {
                Enrollments = new List<Enrollment> { new Enrollment { CourseID = 1 } }
            };

            // Assert
            Assert.Single(student.Enrollments);
        }

        [Fact]
        public void Instructor_FullName_ReturnsConcatenatedLastAndFirst()
        {
            // Arrange
            var instructor = new Instructor { LastName = "Abercrombie", FirstMidName = "Kim" };

            // Act
            var fullName = instructor.FullName;

            // Assert
            Assert.Equal("Abercrombie, Kim", fullName);
        }

        [Fact]
        public void Student_Validation_RequiresLastName()
        {
            // Arrange
            var student = new Student
            {
                FirstMidName = "John",
                EnrollmentDate = DateTime.Now
            };

            // Act
            var results = ValidateModel(student);

            // Assert
            Assert.Contains(results, r => r.MemberNames.Any(m => m == "LastName"));
        }

        [Fact]
        public void Student_Validation_RequiresFirstName()
        {
            // Arrange
            var student = new Student
            {
                LastName = "Smith",
                EnrollmentDate = DateTime.Now
            };

            // Act
            var results = ValidateModel(student);

            // Assert
            Assert.Contains(results, r => r.MemberNames.Any(m => m == "FirstMidName"));
        }

        [Fact]
        public void Student_Validation_LastNameMaxLength50()
        {
            // Arrange
            var student = new Student
            {
                LastName = new string('A', 51),
                FirstMidName = "John",
                EnrollmentDate = DateTime.Now
            };

            // Act
            var results = ValidateModel(student);

            // Assert
            Assert.Contains(results, r => r.MemberNames.Any(m => m == "LastName"));
        }

        [Fact]
        public void Student_Validation_ValidStudent_NoErrors()
        {
            // Arrange
            var student = new Student
            {
                LastName = "Smith",
                FirstMidName = "John",
                EnrollmentDate = DateTime.Parse("2023-09-01")
            };

            // Act
            var results = ValidateModel(student);

            // Assert
            Assert.Empty(results);
        }

        #endregion

        #region Course

        [Fact]
        public void Course_Validation_TitleMinLength3()
        {
            // Arrange
            var course = new Course
            {
                CourseID = 1,
                Title = "AB",
                Credits = 3,
                DepartmentID = 1
            };

            // Act
            var results = ValidateModel(course);

            // Assert
            Assert.Contains(results, r => r.MemberNames.Any(m => m == "Title"));
        }

        [Fact]
        public void Course_Validation_CreditsRange0To5()
        {
            // Arrange
            var course = new Course
            {
                CourseID = 1,
                Title = "Chemistry",
                Credits = 6,
                DepartmentID = 1
            };

            // Act
            var results = ValidateModel(course);

            // Assert
            Assert.Contains(results, r => r.MemberNames.Any(m => m == "Credits"));
        }

        [Fact]
        public void Course_Validation_ValidCourse_NoErrors()
        {
            // Arrange
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1
            };

            // Act
            var results = ValidateModel(course);

            // Assert
            Assert.Empty(results);
        }

        [Fact]
        public void Course_Validation_NegativeCredits_Fails()
        {
            // Arrange
            var course = new Course
            {
                CourseID = 1,
                Title = "Test Course",
                Credits = -1,
                DepartmentID = 1
            };

            // Act
            var results = ValidateModel(course);

            // Assert
            Assert.Contains(results, r => r.MemberNames.Any(m => m == "Credits"));
        }

        #endregion

        #region Department

        [Fact]
        public void Department_Validation_NameMinLength3()
        {
            // Arrange
            var dept = new Department
            {
                Name = "AB",
                Budget = 100000,
                StartDate = DateTime.Now
            };

            // Act
            var results = ValidateModel(dept);

            // Assert
            Assert.Contains(results, r => r.MemberNames.Any(m => m == "Name"));
        }

        [Fact]
        public void Department_InstructorID_IsNullable()
        {
            // Arrange & Act
            var dept = new Department
            {
                Name = "TestDept",
                Budget = 100000,
                StartDate = DateTime.Now,
                InstructorID = null
            };

            // Assert
            Assert.Null(dept.InstructorID);
        }

        #endregion

        #region Enrollment

        [Fact]
        public void Enrollment_Grade_IsNullable()
        {
            // Arrange & Act
            var enrollment = new Enrollment
            {
                EnrollmentID = 1,
                CourseID = 1050,
                StudentID = 1
            };

            // Assert
            Assert.Null(enrollment.Grade);
        }

        [Fact]
        public void Enrollment_GradeValues_CorrectOrder()
        {
            // Assert
            Assert.Equal(0, (int)Grade.A);
            Assert.Equal(1, (int)Grade.B);
            Assert.Equal(2, (int)Grade.C);
            Assert.Equal(3, (int)Grade.D);
            Assert.Equal(4, (int)Grade.F);
        }

        #endregion

        #region ErrorViewModel

        [Fact]
        public void ErrorViewModel_ShowRequestId_TrueWhenSet()
        {
            // Arrange
            var model = new ErrorViewModel { RequestId = "abc123" };

            // Assert
            Assert.True(model.ShowRequestId);
        }

        [Fact]
        public void ErrorViewModel_ShowRequestId_FalseWhenNull()
        {
            // Arrange
            var model = new ErrorViewModel { RequestId = null };

            // Assert
            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void ErrorViewModel_ShowRequestId_FalseWhenEmpty()
        {
            // Arrange
            var model = new ErrorViewModel { RequestId = "" };

            // Assert
            Assert.False(model.ShowRequestId);
        }

        #endregion

        #region Notification

        [Fact]
        public void Notification_Validation_RequiresEntityType()
        {
            // Arrange
            var notification = new Notification
            {
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test",
                CreatedAt = DateTime.Now
            };

            // Act
            var results = ValidateModel(notification);

            // Assert
            Assert.Contains(results, r => r.MemberNames.Any(m => m == "EntityType"));
        }

        [Fact]
        public void Notification_IsRead_DefaultsFalse()
        {
            // Arrange & Act
            var notification = new Notification();

            // Assert
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void Notification_ReadAt_IsNullable()
        {
            // Arrange & Act
            var notification = new Notification();

            // Assert
            Assert.Null(notification.ReadAt);
        }

        [Fact]
        public void EntityOperation_HasCorrectValues()
        {
            // Assert
            Assert.Equal(0, (int)EntityOperation.CREATE);
            Assert.Equal(1, (int)EntityOperation.UPDATE);
            Assert.Equal(2, (int)EntityOperation.DELETE);
        }

        #endregion

        #region OfficeAssignment

        [Fact]
        public void OfficeAssignment_LocationMaxLength50()
        {
            // Arrange
            var oa = new OfficeAssignment
            {
                InstructorID = 1,
                Location = new string('A', 51)
            };

            // Act
            var results = ValidateModel(oa);

            // Assert
            Assert.Contains(results, r => r.MemberNames.Any(m => m == "Location"));
        }

        #endregion

        #region CourseAssignment

        [Fact]
        public void CourseAssignment_SetsPropertiesCorrectly()
        {
            // Arrange & Act
            var ca = new CourseAssignment
            {
                InstructorID = 5,
                CourseID = 1050
            };

            // Assert
            Assert.Equal(5, ca.InstructorID);
            Assert.Equal(1050, ca.CourseID);
        }

        #endregion

        #region SchoolViewModels

        [Fact]
        public void InstructorIndexData_Properties_CanBeSet()
        {
            // Arrange & Act
            var data = new ContosoUniversity.Models.SchoolViewModels.InstructorIndexData
            {
                Instructors = new List<Instructor> { new Instructor { LastName = "Test", FirstMidName = "T" } },
                Courses = new List<Course> { new Course { CourseID = 1, Title = "TestCourse" } },
                Enrollments = new List<Enrollment>()
            };

            // Assert
            Assert.Single(data.Instructors);
            Assert.Single(data.Courses);
            Assert.Empty(data.Enrollments);
        }

        [Fact]
        public void AssignedCourseData_Properties_CanBeSet()
        {
            // Arrange & Act
            var data = new ContosoUniversity.Models.SchoolViewModels.AssignedCourseData
            {
                CourseID = 1050,
                Title = "Chemistry",
                Assigned = true
            };

            // Assert
            Assert.Equal(1050, data.CourseID);
            Assert.Equal("Chemistry", data.Title);
            Assert.True(data.Assigned);
        }

        [Fact]
        public void EnrollmentDateGroup_Properties_CanBeSet()
        {
            // Arrange & Act
            var group = new ContosoUniversity.Models.SchoolViewModels.EnrollmentDateGroup
            {
                EnrollmentDate = DateTime.Parse("2023-09-01"),
                StudentCount = 5
            };

            // Assert
            Assert.Equal(DateTime.Parse("2023-09-01"), group.EnrollmentDate);
            Assert.Equal(5, group.StudentCount);
        }

        #endregion

        private static IList<ValidationResult> ValidateModel(object model)
        {
            var results = new List<ValidationResult>();
            var context = new ValidationContext(model);
            Validator.TryValidateObject(model, context, results, true);
            return results;
        }
    }
}

