using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class SchoolContextTests
    {
        [Fact]
        public void SchoolContext_CanCreateWithInMemoryProvider()
        {
            // Arrange & Act
            using var context = TestDbContextHelper.CreateContext();

            // Assert
            Assert.NotNull(context);
            Assert.NotNull(context.Students);
            Assert.NotNull(context.Courses);
            Assert.NotNull(context.Departments);
            Assert.NotNull(context.Instructors);
            Assert.NotNull(context.Enrollments);
            Assert.NotNull(context.OfficeAssignments);
            Assert.NotNull(context.CourseAssignments);
            Assert.NotNull(context.Notifications);
            Assert.NotNull(context.People);
        }

        [Fact]
        public void SchoolContext_CanAddAndRetrieveStudent()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2023-01-01")
            };

            // Act
            context.Students.Add(student);
            context.SaveChanges();

            // Assert
            var retrieved = context.Students.First();
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal("Student", retrieved.LastName);
            Assert.Equal(DateTime.Parse("2023-01-01"), retrieved.EnrollmentDate);
        }

        [Fact]
        public void SchoolContext_CourseAssignment_CompositeKey()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Instructor",
                HireDate = DateTime.Parse("2020-01-01"),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            context.Instructors.Add(instructor);

            var dept = new Department
            {
                Name = "TestDept",
                Budget = 100000,
                StartDate = DateTime.Now,
                InstructorID = instructor.ID
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course
            {
                CourseID = 5000,
                Title = "TestCourse",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            context.Courses.Add(course);
            context.SaveChanges();

            // Act
            var assignment = new CourseAssignment
            {
                InstructorID = instructor.ID,
                CourseID = course.CourseID
            };
            context.CourseAssignments.Add(assignment);
            context.SaveChanges();

            // Assert
            var retrieved = context.CourseAssignments.First();
            Assert.Equal(instructor.ID, retrieved.InstructorID);
            Assert.Equal(course.CourseID, retrieved.CourseID);
        }

        [Fact]
        public void SchoolContext_OfficeAssignment_OneToOneWithInstructor()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Instructor",
                HireDate = DateTime.Parse("2020-01-01"),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            // Act
            var office = new OfficeAssignment
            {
                InstructorID = instructor.ID,
                Location = "Room 101"
            };
            context.OfficeAssignments.Add(office);
            context.SaveChanges();

            // Assert
            var retrieved = context.OfficeAssignments.First();
            Assert.Equal(instructor.ID, retrieved.InstructorID);
            Assert.Equal("Room 101", retrieved.Location);
        }

        [Fact]
        public void SchoolContext_CanAddAndRetrieveNotification()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "New Student created",
                CreatedAt = DateTime.Now,
                CreatedBy = "Admin",
                IsRead = false
            };

            // Act
            context.Notifications.Add(notification);
            context.SaveChanges();

            // Assert
            var retrieved = context.Notifications.First();
            Assert.Equal("Student", retrieved.EntityType);
            Assert.Equal("1", retrieved.EntityId);
            Assert.Equal("CREATE", retrieved.Operation);
            Assert.Equal("New Student created", retrieved.Message);
            Assert.False(retrieved.IsRead);
        }

        [Fact]
        public void SchoolContext_StudentAndInstructor_SharePersonBase()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            context.Students.Add(new Student
            {
                FirstMidName = "StudentFirst",
                LastName = "StudentLast",
                EnrollmentDate = DateTime.Now
            });
            context.Instructors.Add(new Instructor
            {
                FirstMidName = "InstructorFirst",
                LastName = "InstructorLast",
                HireDate = DateTime.Now,
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            });
            context.SaveChanges();

            // Act
            var people = context.People.ToList();

            // Assert
            Assert.Equal(2, people.Count);
            Assert.Contains(people, p => p is Student);
            Assert.Contains(people, p => p is Instructor);
        }
    }
}

